import os
from dataclasses import dataclass
from typing import Optional

# === dataclass：简化数据类定义 ===
# 第1步：用 @dataclass 装饰器 —— 自动生成 __init__/__repr__，省去样板代码
@dataclass
class Tool:
    name: str
    description: str
    enabled: bool = True

# 第2步：定义基类 BaseAgent —— 抽象出 Agent 的公共接口（模板方法）
# === 继承 ===
class BaseAgent:
    def __init__(self, name: str):
        self.name = name

    def run(self, query: str) -> str:
        raise NotImplementedError

# 第3步：继承 BaseAgent 实现 ReActAgent —— 复用父类接口并扩展工具能力
class ReActAgent(BaseAgent):
    def __init__(self, name: str, tools: list[Tool]):
        # 第4步：super().__init__ 复用父类构造 —— 避免重复初始化 name
        super().__init__(name)
        self.tools = tools

    # 第5步：重写 run 方法 —— 子类提供具体行为，体现多态
    def run(self, query: str) -> str:
        return f"{self.name} processing: {query}"

# === 装饰器 ===
# 第6步：实现重试装饰器 —— 把失败重试逻辑与业务代码解耦
def retry(max_attempts: int = 3):
    """重试装饰器：Agent 开发常用"""
    def decorator(func):
        def wrapper(*args, **kwargs):
            # 第7步：循环发起调用并捕获异常 —— 未达上限则重试，达到则抛出
            # 这样临时故障也能自动恢复，提升 Agent 调用 LLM 的健壮性
            for attempt in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempt == max_attempts - 1:
                        raise
                    print(f"Attempt {attempt+1} failed: {e}")
        return wrapper
    # 第8步：用 @retry 装饰 call_llm —— 无需改函数体即获得重试能力
    return decorator

@retry(max_attempts=3)
def call_llm(prompt: str) -> str:
    """带重试的 LLM 调用"""
    return "response"

# 使用
# 第9步：实例化并调用 —— ReActAgent 组合 Tool，run 返回处理结果
agent = ReActAgent("Assistant", [Tool("search", "搜索")])
print(agent.run("hello"))

from typing import Optional, Union, Literal, Callable, TypedDict
from dataclasses import dataclass

# === 基础容器与可选类型 ===
# 第1步：list/dict/tuple 泛型 —— 标注集合内部元素类型
def get_names(users: list[str]) -> list[str]:
    return [u for u in users if u]

# 第2步：Optional[X] 等价于 Union[X, None] —— 明确该参数可空
def find_tool(name: str) -> Optional[str]:
    return name if name else None

# 第3步：Union —— 参数接受多种类型之一
def parse_id(raw: Union[int, str]) -> int:
    return int(raw)

# === Literal：限定取值集合 ===
# 第4步：Literal —— 把参数限制为几个固定字符串，常用于模型/角色枚举
Role = Literal["user", "assistant", "system"]

def role_prefix(role: Role) -> str:
    return {"user": "U", "assistant": "A", "system": "S"}[role]

# === TypedDict：结构化字典 ===
# 第5步：TypedDict —— 给 dict 加字段类型约束，适合 LLM messages 这类固定结构
class Message(TypedDict):
    role: Role
    content: str

msg: Message = {"role": "user", "content": "你好"}

# === Callable：函数类型 ===
# 第6步：Callable[[参数类型...], 返回类型] —— 标注回调/工具函数签名
Handler = Callable[[str], str]

def dispatch(fn: Handler, text: str) -> str:
    return fn(text)

if __name__ == "__main__":
    print(get_names(["a", "b"]))
    print(find_tool(""))           # None
    print(parse_id("42"))          # 42
    print(role_prefix("system"))   # S
    print(msg)                     # {'role': 'user', 'content': '你好'}
    print(dispatch(str.upper, "hi"))  # HI

from functools import wraps
import time

# === 内置装饰器 ===
class Agent:
    def __init__(self, name: str):
        self.name = name

    # 第1步：@property —— 把方法变成只读属性，调用时无需加 ()
    @property
    def greet(self) -> str:
        return f"Hello, I'm {self.name}"

    # 第2步：@staticmethod —— 不依赖实例/类状态的方法
    @staticmethod
    def version() -> str:
        return "1.0"

# === 自定义装饰器（带 functools.wraps）===
# 第3步：functools.wraps 保留原函数元信息（__name__/__doc__），避免被装饰后信息丢失
def log_calls(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        print(f"[log] 调用 {func.__name__} args={args} kwargs={kwargs}")
        return func(*args, **kwargs)
    return wrapper

# 第4步：带参数的装饰器 —— 外层接收参数，返回真正装饰器
def retry(max_attempts: int = 3):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for i in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if i == max_attempts - 1:
                        raise
                    print(f"[retry] 第{i+1}次失败: {e}")
        return wrapper
    return decorator

@log_calls
@retry(max_attempts=3)
def call_llm(prompt: str) -> str:
    if prompt == "":
        raise ValueError("空 prompt")
    return f"回复: {prompt}"

if __name__ == "__main__":
    a = Agent("ReAct")
    print(a.greet)          # Hello, I'm ReAct
    print(Agent.version())  # 1.0
    print(call_llm("你好"))  # 打印日志 + 回复
    try:
        call_llm("")        # 触发重试并最终抛出
    except ValueError as e:
        print("捕获:", e)

from functools import lru_cache, partial, reduce, wraps

# === lru_cache：记忆化缓存 ===
# 第1步：缓存函数结果，相同入参直接返回，避免重复昂贵计算（如重复 LLM 调用）
@lru_cache(maxsize=128)
def expensive(n: int) -> int:
    print(f"计算 expensive({n})")
    return n * n

# === partial：偏函数 ===
# 第2步：固定部分参数生成新函数，常用于预设工具/客户端配置
def call_model(model: str, prompt: str) -> str:
    return f"[{model}] {prompt}"

gpt5 = partial(call_model, "gpt-5")   # 预设模型

# === wraps：保留被装饰函数元信息 ===
def tag(fn):
    @wraps(fn)
    def wrapper(*a, **k):
        return fn(*a, **k)
    return wrapper

# === reduce：累积归约 ===
# 第3步：把序列按二元操作累积成单值
product = partial(reduce, lambda x, y: x * y)

if __name__ == "__main__":
    print(expensive(4))   # 计算并打印
    print(expensive(4))   # 直接命中缓存，无打印
    print(gpt5("你好"))    # [gpt-5] 你好
    print(product([1, 2, 3, 4]))  # 24
